assert sum(range(1, 21)) == 210 and sum(range(1, 101)) == 5050 and sum(range(1, 7)) == 21
assert sum(2*i-1 for i in range(1, 16)) == 225 and sum(2*i-1 for i in range(11, 26)) == 525
assert sum(2*i-1 for i in range(2, 12)) == 120 and 8*7//2 == 28 and 9*8//2 == 36
assert 3 + 4*7 - 3 == 28 and 3 + 4*9 == 39
assert sum(i**3 for i in range(1, 6)) == 225 == 15**2

